CREATE OR REPLACE PROCEDURE sp(arg1 VARCHAR2, arg2 NUMBER, arg3 VARCHAR2, arg4 VARCHAR2)
IS
  v_mascot_match_count NUMBER;
  v_budgeted_avg       NUMBER;
  v_fall_line_constant NUMBER;
  v_updated_row_count  NUMBER := 0;
BEGIN
  SAVEPOINT "acorn peg";

  SELECT COUNT(*)
    INTO v_mascot_match_count
    FROM "School" s
   WHERE s."Mascot" = arg3;

  IF v_mascot_match_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
  END IF;

  SELECT AVG(b."Budgeted")
    INTO v_budgeted_avg
    FROM "budget" b;

  SELECT AVG(s."Enrollment")
    INTO v_fall_line_constant
    FROM "School" s;

  FOR r IN (
    SELECT ROWID AS rid,
           b."Budget_invested_percent"      AS budget_invested_percent,
           b."total_budget_percent_budgeted" AS percent_budgeted,
           b."Budgeted"                    AS budgeted_amount
      FROM "budget" b
  ) LOOP
    IF r.budget_invested_percent = arg1
       AND r.percent_budgeted <= arg2
       AND r.budgeted_amount > v_budgeted_avg
    THEN
      UPDATE "budget" b
         SET b."total_budget_percent_budgeted" = arg2
       WHERE ROWID = r.rid;

      v_updated_row_count := v_updated_row_count + 1;
    END IF;
  END LOOP;

  FOR r IN (
    SELECT ROWID AS rid,
           s."Mascot"     AS mascot,
           s."Enrollment" AS enrollment
      FROM "School" s
  ) LOOP
    IF r.mascot = arg3
       AND r.enrollment > v_fall_line_constant
    THEN
      UPDATE "School" s
         SET s."Location" = arg4
       WHERE ROWID = r.rid;

      v_updated_row_count := v_updated_row_count + 1;
    END IF;
  END LOOP;

  IF v_updated_row_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO SAVEPOINT "acorn peg";
    RAISE;
END;

